function copSight(a,b){let d=Math.hypot(b.x-a.x,b.z-a.z),n=Math.ceil(d/.6);for(let j=1;j<n;j++)if(blocked(a.x+(b.x-a.x)*j/n,a.z+(b.z-a.z)*j/n))return false;return true;}
